def choose_move(observation):
    obs = observation or {}
    ax = obs.get("self_position", {}).get("x",
         obs.get("position", {}).get("x", 0))
    ay = obs.get("self_position", {}).get("y",
         obs.get("position", {}).get("y", 0))
    ox = obs.get("opponent_position", {}).get("x", 0)
    oy = obs.get("opponent_position", {}).get("y", 0)

    # If resources exist, move toward the nearest resource
    resources = obs.get("resources", [])
    if isinstance(resources, list) and resources:
        best = None
        best_dist = None
        for r in resources:
            if isinstance(r, dict):
                rx = r.get("x")
                ry = r.get("y")
            else:
                if len(r) >= 2:
                    rx, ry = r[0], r[1]
                else:
                    continue
            dist = (rx - ax) * (rx - ax) + (ry - ay) * (ry - ay)
            if best_dist is None or dist < best_dist:
                best_dist = dist
                best = (rx, ry)
        if best is not None:
            rx, ry = best
            dx = 1 if rx > ax else -1 if rx < ax else 0
            dy = 1 if ry > ay else -1 if ry < ay else 0
            return [dx, dy]

    # Otherwise, simple chase away from opponent if too close, else hover toward center
    dx = 0
    dy = 0
    if ax == ox and ay == oy:
        dx, dy = 0, 1
    else:
        dx = 1 if ox > ax else -1 if ox < ax else 0
        dy = 1 if oy > ay else -1 if oy < ay else 0
        # If opponent is diagonally far, adjust to reduce distance
        if abs(ox - ax) > 1 or abs(oy - ay) > 1:
            pass

    return [dx, dy]
